// Extrae el mensaje entrante del cliente. Si el webhook es un estado
// (entregado/leído) o no es texto, no devuelve nada (se ignora).
const body = $json.body || $json;
const value = (((body.entry || [])[0] || {}).changes || [])[0]?.value || {};
const msg = (value.messages || [])[0];
if (!msg) { return []; }
const from = msg.from || '';
const last10 = String(from).replace(/\D/g, '').slice(-10);
let texto = '';
if (msg.type === 'text') texto = msg.text?.body || '';
else if (msg.type === 'interactive') texto = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
if (!texto) { return []; }
return [{ json: { from, last10, texto } }];

// Personalidad del asistente (tono: usted cálido y cercano) + arma el
// contexto real de la orden para que la IA no invente.
const SYSTEM = `Eres "Asistente Freimanautos", el asesor virtual del taller automotriz Freimanautos (Colombia). Hablas con un cliente por WhatsApp sobre SU vehículo.

TONO: usted, cálido y cercano, claro y breve, como un asesor amable del taller (no como un robot). Máximo 1-2 emojis por mensaje. Sin tecnicismos innecesarios. Respuestas cortas: 2 a 4 frases.

SOLO SABES lo que viene en el CONTEXTO. Si preguntan algo que NO está ahí, no lo inventes.

PUEDES responder sobre: estado y avance del vehículo, en qué etapa va, novedades, fecha estimada de entrega, horario de atención y ubicación del taller.

DEBES ESCALAR a un humano cuando pregunten por: precios, cotizaciones o valores; reclamos o quejas; autorizar trabajos o repuestos; cambios de cita; o si piden hablar con una persona; o cualquier tema que no puedas responder con el contexto. Para escalar, responde SOLO algo como "Permítame y un asesor le confirma eso enseguida 🙏" e incluye al final la marca [ESCALAR].

REGLAS: no prometas fechas exactas que no estén en el contexto; no des información de otros vehículos; si no hay orden asociada, pida con amabilidad la placa o la cédula.

DATOS DEL TALLER: horario Lunes a viernes 8:00am-6:00pm, sábados 8:00am-1:00pm; dirección (PON AQUÍ LA DIRECCIÓN DEL TALLER).`;

const m = $('Leer mensaje del cliente').item.json;
const arr = Array.isArray($json) ? $json : (Array.isArray($json.body) ? $json.body : []);
const o = arr[0];
let contexto;
if (!o) {
  contexto = 'No se encontró ninguna orden asociada a este número. Pida con amabilidad la placa o la cédula.';
} else {
  const ets = o.etapas || [];
  const activa = ets.find(e => e.inicio && !e.fin);
  const sig = ets.find(e => !e.inicio);
  const total = ets.length;
  const comp = ets.filter(e => e.fin).length;
  const novs = (o.novedades || []).slice(0, 3).map(n => `- ${n.tipo}: ${n.motivo}`).join('\n') || 'ninguna';
  contexto = `Placa: ${o.placa}\nVehículo: ${[o.marca, o.linea, o.modelo].filter(Boolean).join(' ')}\nEstado: ${o.estado}\nAvance: ${comp} de ${total} etapas\nEtapa actual: ${activa ? activa.etapa + (activa.pausado ? ' (en pausa, esperando un repuesto)' : ' (en proceso)') : 'sin etapa activa por ahora'}\nPróxima etapa: ${sig ? sig.etapa : 'no hay'}\nFecha estimada de entrega: ${o.fecha_entrega_1 || 'sin definir'}\nNovedades recientes:\n${novs}`;
}
return [{ json: { from: m.from, texto: m.texto, contexto, system: SYSTEM } }];

