// Toma la respuesta de la IA y detecta si pidió escalar a humano.
const data = $json;
const raw = data?.choices?.[0]?.message?.content || '';
const escalar = /\[ESCALAR\]/i.test(raw);
let reply = raw.replace(/\[ESCALAR\]/ig, '').trim();
if (!reply) reply = 'Permítame y un asesor le escribe enseguida 🙏';
const ctx = $('Armar contexto').item.json;
return [{ json: { reply, escalar, from: ctx.from, texto: ctx.texto } }];
